on conflict (venue_id, master_item_id) do update
  set cost_per_unit = excluded.cost_per_unit, source = excluded.source, set_by = excluded.set_by,
      is_manual = false, price_date = excluded.price_date, updated_at = now();

do $$
declare n int; n_bad int;
begin
  select count(*) into n from public.kount_venue_cost_overrides where venue_id = 'v13';
  select count(*) into n_bad from public.kount_venue_cost_overrides o
   where o.venue_id = 'v13' and not exists (
     select 1 from public.venue_item_settings s
      where s.venue_id = '2b331b4f-8cf1-4c24-a795-3792b4cf724d' and s.master_item_id = o.master_item_id);
  if n <> 247 or n_bad <> 0 then
    raise exception 'shishi cost check failed: rows=% not-a-shishi-item=%', n, n_bad;
  end if;
  raise notice 'ok: % v13 cost rows', n;
end $$;

